query GetPublicServiceImplementationsPaginated($searchTerms: [String], $where: ServiceImplementationFilterInput!, $pageSize: Int!, $after: Int, $orderBy: [OrderByInput]) {
  serviceImplementation {
    allServiceImplementationsPaginated(
      skip: $after
      take: $pageSize
      where: $where
      searchTerms: $searchTerms
      orderBy: $orderBy
    ) {
      pageInfo {
        hasNextPage
        hasPreviousPage
      }
      totalCount
      items {
        token
        modified
        names {
          language
          value
        }
        code
        capacity
        status
        area {
          municipalities {
            code
            names {
              language
              value
            }
          }
        }
        nonStop
        startDate
        endDate
        publicationStartDate
        publicationEndDate
        implementationDurationDescription {
          language
          value
        }
        implementationType
        languages {
          languageCode
        }
        registrationWebPages {
          language
          value
          url
        }
        addressInfo {
          value
          language
        }
        serviceOffering {
          token
          organizations {
            roleType
            organization {
              token
              names {
                language
                value
              }
            }
          }
          service {
            token
            names {
              language
              value
            }
            category {
              code
            }
          }
        }
      }
    }
  }
}

query GetPublicServiceImplementation($token: ID!) {
  serviceImplementation {
    serviceImplementation(token: $token) {
      token
      modified
      names {
        language
        value
      }
      code
      status
      capacity
      nonStop
      startDate
      endDate
      publicationStartDate
      publicationEndDate
      implementationDurationDescription {
        language
        value
      }
      additionalInformation {
        language
        value
      }
      addressInfo {
        language
        value
      }
      area {
        municipalities {
          code
          names {
            language
            value
          }
        }
      }
      serviceOffering {
        token
        startDate
        endDate
        organizations {
          provisionType
          roleType
          organization {
            token
            names {
              language
              value
            }
          }
        }
        service {
          token
          origin
          names {
            language
            value
          }
          category {
            code
            name {
              language
              value
            }
          }
        }
      }
      implementationType
      languages {
        languageCode
      }
      languageSkillLevels {
        languageCode
        level
        type
      }
      registrationWebPages {
        language
        value
        url
      }
      webPages {
        language
        value
        url
      }
      holidayPeriods {
        startDate
        endDate
      }
    }
  }
}

query GetPublicService($token: Uuid!) {
  service {
    services(where: {or: [{ptvToken: {eq: $token}}, {token: {eq: $token}}]}) {
      token
      ptvToken
      courseNumber
      category {
        code
        parentCode
        name {
          language
          value
        }
      }
      type
      status
      modified
      origin
      publicationStartDate
      publicationEndDate
      responsibleOrganization {
        token
        names {
          language
          value
          type
        }
      }
      names {
        language
        value
        type
      }
      languages {
        languageCode
      }
      areaType
      chargeType
      description {
        language
        value
      }
      userInstruction {
        language
        value
      }
      requirements {
        language
        value
      }
      summary {
        language
        value
      }
      targetGroups {
        targetGroupCode
      }
      serviceOfferings {
        token
        serviceImplementations {
          token
        }
      }
    }
  }
}

query GetCategories($language: String!) {
  ontology {
    serviceCategories {
      ...Categories
    }
  }
}

fragment Categories on ServiceCategory {
  allowedForServiceTypes
  code
  name(language: $language) {
    language
    value
  }
  parentCode
  appropriation
  atmtEditable
  startDate
  endDate
}
